function toggleActive(selectedEl) {
const group = selectedEl.parentElement; group.querySelectorAll('%1$s').forEach(el => el.classList.remove('%2$s')); selectedEl.classList.add('%3$s');
}

new IntersectionObserver((entries) => {
entries.forEach(entry => {
if (entry.isIntersecting) entry.target.classList.add('%1$s');
});
}, {
threshold: 0.1
}).observe(document.querySelector('%2$s'));
